async function photos(){const run=++renderRun;for(const img of document.querySelectorAll('img[data-photo]')){const path=img.dataset.photo;try{let url=photoURLs.get(path);if(!url){const {data,error}=await client.storage.from('fridge-images').download(path);if(error)throw error;if(run!==renderRun)return;url=URL.createObjectURL(data);photoURLs.set(path,url);}if(run!==renderRun||!img.isConnected)return;img.src=url;img.hidden=false;}catch{img.hidden=true;}}}
