async function loadCheckoutRate(){const f=$('fr-form'),rate=f.elements.checkout_rate,marker=$('fr-checkout-rate-status');if(!rate||!marker||rate.value||marker.dataset.loading==='true')return;marker.dataset.loading='true';marker.textContent='Consultando cambio… Puedes escribirlo.';try{const {data:{session}}=await client.auth.getSession();if(!session)throw Error();const response=await fetch('https://jhumvctocphyiwhszeaz.supabase.co/functions/v1/dashboard-eltoque-rates',{headers:{Authorization:'Bearer '+session.access_token}});if(!response.ok)throw Error();const result=await response.json(),value=Number(result.rates?.USD);if(!Number.isFinite(value)||value<=0||value>1000000||result.stale)throw Error();if(!marker.isConnected)return;if(!rate.value){rate.value=value;f.elements.checkout_rate_source.value='reference';marker.textContent='Referencia elTOQUE · editable.';}else marker.textContent='Usa la tasa acordada para este cobro.';syncCheckout(false);if(f.elements.account_payment)syncAccountPayment(true);}catch{if(marker.isConnected)marker.textContent='Usa la tasa acordada para este cobro.';}finally{if(marker.isConnected)marker.dataset.loading='false';}}
function paymentForm(){if(!account)return;const recipient=account.id,balance=Number(account.balance);openForm('Registrar cobro','<p class="fr-note">'+esc(account.name)+' · Pendiente: '+money(balance)+'</p><input type="hidden" name="account_payment" value="1">'+select('Moneda de cobro','payment_currency',option('USD','USD')+option('CUP','CUP'))+'<div id="fr-checkout-rate-panel" class="fr-checkout-rate" hidden><h3>Cambio del día</h3><label class="fr-checkout-rate-row"><span>1 USD =</span><input aria-label="Cambio del día, CUP por 1 USD" name="checkout_rate" type="number" min="0.0001" max="1000000" step="0.0001" inputmode="decimal" placeholder="0.00"><span>CUP</span></label><input type="hidden" name="checkout_rate_source" value="manual"><p class="fr-muted" id="fr-checkout-rate-status" role="status">Usa la tasa acordada para este cobro.</p></div><div class="fr-form-grid"><label><span id="fr-account-amount-label">Importe a cobrar · USD *</span><input name="amount" type="number" value="'+balance.toFixed(2)+'" min="0.01" step="0.01" inputmode="decimal" required></label>'+select('Medio de cobro','method',option('cash','Efectivo')+option('transfer','Transferencia'))+'</div><p id="fr-account-payment-preview" class="fr-note" role="status" aria-live="polite"></p>'+noteField(),'Confirmar cobro',f=>{const raw=Number(f.get('amount')),currency=f.get('payment_currency'),rate=currency==='CUP'?Number(f.get('checkout_rate')):1;if(!Number.isFinite(raw)||raw<=0||!Number.isFinite(rate)||rate<=0||rate>1000000)throw Error('Revisa el importe y la tasa de cambio.');const amount=Math.round((raw/rate+Number.EPSILON)*100)/100;if(amount<=0||amount>balance)throw Error('El cobro debe ser mayor que cero y no superar la deuda.');return command('payment',{customer_id:recipient,amount,collection:{currency,amount:raw,rate,source:currency==='CUP'?f.get('checkout_rate_source')||'manual':'manual'},method:f.get('method'),note:f.get('note').trim()});});const f=$('fr-form');f.dataset.paymentUsd=String(balance);f.dataset.paymentBalance=String(balance);dialog.classList.add('fr-payment-dialog');syncAccountPayment(true);}
function syncAccountPayment(convert=false){const f=$('fr-form');if(!f.elements.account_payment)return;const cup=f.elements.payment_currency.value==='CUP',rate=cup?Number(f.elements.checkout_rate.value):1,valid=Number.isFinite(rate)&&rate>0&&rate<=1000000,balance=Number(f.dataset.paymentBalance);$('fr-checkout-rate-panel').hidden=!cup;f.elements.checkout_rate.disabled=!cup;f.elements.checkout_rate.required=cup;$('fr-account-amount-label').textContent='Importe a cobrar · '+(cup?'CUP':'USD')+' *';if(convert)f.elements.amount.value=valid?(Math.round(Number(f.dataset.paymentUsd)*rate*100)/100).toFixed(2):'';const usd=valid?Math.round((Number(f.elements.amount.value)/rate+Number.EPSILON)*100)/100:0;if(!convert&&valid)f.dataset.paymentUsd=String(usd);if(valid)f.elements.amount.max=(Math.round(balance*rate*100)/100).toFixed(2);else f.elements.amount.removeAttribute('max');$('fr-account-payment-preview').textContent=!valid?'Declara el cambio para calcular el cobro.':(cup?'Equivale a '+money(usd)+' · ':'')+(usd>=balance?'Pago completo':'Saldo restante: '+money(Math.max(0,balance-usd)));if(cup&&!f.elements.checkout_rate.value)void loadCheckoutRate();}

