function photoField(p){return '<section class="fr-photo-field" aria-label="Fotografía del producto"><h3>Fotografía del producto</h3><div class="fr-photo-row"><div id="fr-photo-box" class="fr-photo-box" aria-busy="false">'+(p?.photo_path?'<img data-photo="'+esc(p.photo_path)+'" alt="Fotografía actual del producto" hidden>':icon('fridge')+'<small>Fotografía del producto</small>')+'<img id="fr-photo-preview" alt="Fotografía preparada" hidden><span id="fr-photo-overlay" hidden><span class="fr-photo-spinner"></span>Preparando…</span></div><div class="fr-photo-controls"><div class="fr-photo-buttons"><label class="fr-secondary">'+icon('camera')+'Tomar foto<input id="fr-photo-camera" type="file" accept="image/*" capture="environment"></label><label class="fr-secondary">'+icon('photo')+'Galería<input id="fr-photo-gallery" type="file" accept="image/*"></label></div><p class="fr-muted">Fondo limpio y foto cuadrada para el catálogo.</p><div id="fr-photo-status" class="fr-photo-status" role="status" aria-live="polite" hidden></div><button type="button" id="fr-photo-retry" class="fr-secondary" disabled>↻ Reintentar limpieza de fondo</button></div></div></section>';}
function syncPhotoRetry(){const b=$('fr-photo-retry');if(!b)return;$('fr-dialog-submit').disabled=busy||photoBusy||!!pending;b.disabled=busy||!!pending||photoBusy||photoCleaned||(!photoSource&&!photoExisting?.photo_path);b.textContent=photoBusy?'Procesando fotografía…':photoCleaned?'✓ Fondo limpio':'↻ Reintentar limpieza de fondo';b.title=photoCleaned?'La limpieza de esta foto está confirmada':photoBusy?'Espera a que termine el procesamiento':(!photoSource&&!photoExisting?.photo_path)?'Selecciona primero una fotografía':'Reintentar con la misma fotografía';}
function photoStatus(text,state='busy',fraction=null){const status=$('fr-photo-status');if(!status)return;status.hidden=!text;status.dataset.state=state;status.replaceChildren();const label=document.createElement('span');label.textContent=text;status.append(label);const active=state==='busy';$('fr-photo-box').setAttribute('aria-busy',String(active));$('fr-photo-overlay').hidden=!active;if(active||state==='ready'){const progress=document.createElement('progress');progress.max=1;if(state==='ready')progress.value=1;else if(Number.isFinite(fraction))progress.value=Math.min(1,Math.max(0,fraction));progress.setAttribute('aria-label',text);status.append(progress);}}
function displayPreparedPhoto(blob){if(photoPreview)URL.revokeObjectURL(photoPreview);photoPreview=URL.createObjectURL(blob);const image=$('fr-photo-preview');image.src=photoPreview;image.hidden=false;}
async function choosePhoto(file){if(!file)return;const generation=++photoGeneration;photoBusy=true;photoSource=file;photoBlob=null;photoCleaned=false;syncPhotoRetry();photoStatus('Preparando fotografía…');displayPreparedPhoto(file);try{const result=await photoService.prepare(file,(text,fraction)=>{if(generation===photoGeneration)photoStatus(text,'busy',fraction);},()=>generation===photoGeneration&&dialog.open);if(generation!==photoGeneration)return;photoBlob=result.blob;photoCleaned=result.cleaned===true;displayPreparedPhoto(photoBlob);photoStatus((photoCleaned?'Fondo limpio · ':result.notice+' · ')+Math.ceil(photoBlob.size/1024)+' KB · se subirá al guardar',photoCleaned?'ready':'warning');}catch(e){if(generation===photoGeneration){photoStatus('No se pudo preparar la fotografía. '+e.message,'error');throw e;}}finally{if(generation===photoGeneration){photoBusy=false;syncPhotoRetry();}}}
