function readPending(){try{pending=JSON.parse(localStorage.getItem(pendingKey())||'null');}catch{throw Error('No se pudo leer el registro pendiente. No crees otro hasta verificarlo.');}renderRecovery();}
async function command(kind,payload){payload={...payload,currency:'USD'};readPending();if(pending)throw Error('Verifica primero el registro pendiente.');pending={id:crypto.randomUUID(),kind,payload};const serialized=JSON.stringify(pending);try{localStorage.setItem(pendingKey(),serialized);if(localStorage.getItem(pendingKey())!==serialized)throw Error();}catch{pending=null;throw Error('No se pudo conservar el registro para protegerlo de duplicados. No se ha enviado.');}renderRecovery();return executePending();}
async function executePending(){const op=pending;if(!op)throw Error('No hay registros pendientes.');try{const result=await rpc('fridge_command',{p_id:op.id,p_kind:op.kind,p_payload:op.payload});localStorage.removeItem(pendingKey());pending=null;if(op.kind==='sale'&&op.payload.sale_context?.kind!=='existing')receiptAfterSave=op.id;if(op.kind==='sale'||op.kind==='loss'&&op.payload.sale_context?.kind==='courtesy')cart.clear();renderRecovery();return result;}catch(e){if(e.code&&/^(P0001|P0002|22|23|42)/.test(e.code)){localStorage.removeItem(pendingKey());pending=null;}renderRecovery();throw e;}}
async function run(fn){if(busy)return;busy=true;$('fr-form').setAttribute('aria-busy','true');syncPhotoRetry();app.setAttribute('aria-busy','true');$('fr-dialog-submit').disabled=true;renderRecovery();try{await fn();}catch(e){message(e.message||'No se pudo confirmar el registro. Verifica su estado antes de repetirlo.',true);if(dialog.open)$('fr-form-error').textContent=e.message||'No se pudo confirmar.';}finally{busy=false;$('fr-form').removeAttribute('aria-busy');syncPhotoRetry();app.setAttribute('aria-busy','false');$('fr-dialog-submit').disabled=false;renderRecovery();}}
